{
    "documents": [
        {
            "title": "Q4 2025 Revenue Report",
            "content": "The company achieved record revenue of $2.4 billion in Q4 2025, representing a 23% year-over-year growth. Cloud services division drove most of the growth with a 45% increase in annual recurring revenue.",
            "docType": "report",
            "tags": ["finance", "quarterly", "revenue", "cloud"],
            "metadata": {"author": "Jane Smith", "department": "Finance"}
        },
        {
            "title": "Q3 2025 Revenue Report",
            "content": "Q3 revenue reached $2.1 billion with strong performance in cloud services and enterprise sales. The company expanded its customer base by 18%.",
            "docType": "report",
            "tags": ["finance", "quarterly", "revenue"],
            "metadata": {"author": "Jane Smith", "department": "Finance"}
        },
        {
            "title": "Annual Budget Forecast 2026",
            "content": "The projected budget for 2026 allocates $800M to R&D, $400M to sales and marketing, and $200M to infrastructure. Cloud migration costs are expected to decrease by 25%.",
            "docType": "report",
            "tags": ["finance", "budget", "forecast"],
            "metadata": {"author": "CFO Office", "department": "Finance"}
        },
        {
            "title": "Microservices Architecture Migration Plan",
            "content": "This document outlines the plan to migrate our monolithic application to a microservices architecture. Phase 1 involves decomposing the authentication and user management modules. We will use Kubernetes for orchestration and Resilience4j for circuit breakers.",
            "docType": "technical",
            "tags": ["architecture", "microservices", "migration", "kubernetes"],
            "metadata": {"author": "Bob Johnson", "department": "Engineering"}
        },
        {
            "title": "API Gateway Migration to Kong",
            "content": "Details the migration from our custom API gateway to Kong Enterprise. Covers rate limiting, JWT validation, and request routing. Expected to reduce infrastructure costs by 30%.",
            "docType": "technical",
            "tags": ["architecture", "migration", "kong"],
            "metadata": {"author": "Bob Johnson", "department": "Engineering"}
        },
        {
            "title": "Database Sharding Strategy",
            "content": "Proposes horizontal sharding of the user database across 8 shards using consistent hashing. Expected to handle 10x current traffic with sub-100ms query latency.",
            "docType": "technical",
            "tags": ["architecture", "database", "scaling"],
            "metadata": {"author": "DBA Team", "department": "Engineering"}
        },
        {
            "title": "Remote Work Policy 2026",
            "content": "Employees may work remotely up to 3 days per week with manager approval. Core collaboration hours are 10 AM to 3 PM local timezone. Quarterly in-person gatherings are mandatory.",
            "docType": "policy",
            "tags": ["hr", "remote-work", "policy"],
            "metadata": {"author": "HR Team", "department": "Human Resources"}
        },
        {
            "title": "Annual Performance Review Guidelines",
            "content": "All employees must complete annual performance reviews by December 15. Managers provide written feedback on achievements, growth areas, and goals for the next year.",
            "docType": "policy",
            "tags": ["hr", "policy", "review"],
            "metadata": {"author": "HR Team", "department": "Human Resources"}
        }
    ]
}

